# fims_retrospective ----
## Setup ----
#' @description Skip the test unless explicitly enabled for heavy integration testing.
testthat::skip_if(
  Sys.getenv("RUN_SLOW_TESTS") != "true",
  "Skipping: RUN_SLOW_TESTS is not set to true."
)

# Load or prepare any necessary data for testing
# clear memory
clear()
## Testing how to remove one year of data and run multiple FIMS models
# Load sample data
data("data_big")
# Prepare data for FIMS model
data_4_model <- FIMSFrame(data_big)
# Create parameters
parameters <- setup_default_parameters(data = data_4_model)
# Fit in parallel
retro_fit <- run_fims_retrospective(
  years_to_remove = 0:1,
  data = data_big,
  parameters = parameters,
  n_cores = 2
)

## IO correctness ----
test_that("run_fims_retrospective() works with correct inputs", {
  #' @description Test that run_fims_retrospective(x) returns y.

  expect_equal(
    object = names(retro_fit),
    expected = c("years_to_remove", "estimates")
  )

  #' @description Test that calculate_mohns_rho() returns a numeric value.

  rho_sb <- calculate_mohns_rho(retro_fit, quantity = "spawning_biomass")

  expect_equal(
    object = class(rho_sb),
    expected = "numeric"
  )

  expect_equal(
    object = length(rho_sb),
    expected = 1
  )

  expect_true(
    object = is.finite(rho_sb) && !is.na(rho_sb)
  )

  #' @description Test that calculate_mohns_rho() returns consistent results across runs.
  rho_sb_1 <- calculate_mohns_rho(retro_fit, quantity = "spawning_biomass")
  rho_sb_2 <- calculate_mohns_rho(retro_fit, quantity = "spawning_biomass")

  expect_equal(
    object = rho_sb_1,
    expected = rho_sb_2
  )

  #' @description Test that calculate_mohns_rho() works with recruitment quantity.
  rho_rec <- calculate_mohns_rho(retro_fit, quantity = "expected_recruitment")

  expect_equal(
    object = class(rho_rec),
    expected = "numeric"
  )

  expect_true(
    object = is.finite(rho_rec) && !is.na(rho_rec)
  )

  #' @description Test that fims_retrospective(x) returns y.
  expect_equal(
    object = length(retro_fit[["years_to_remove"]]),
    expected = 2
  )

  #' @description Test that each peel ends in its last year of data, so it has
  #' no expected catch, fishing mortality, or recruitment deviation after that
  #' year.
  last_years <- retro_fit[["estimates"]] |>
    dplyr::filter(label %in% c("catch_expected", "log_Fmort", "log_devs")) |>
    dplyr::summarise(
      last_year = max(year),
      .by = c(retrospective_peel, label)
    )
  expect_equal(
    object = last_years[["last_year"]],
    expected = get_end_year(data_4_model) - last_years[["retrospective_peel"]]
  )

  # Year 29 is the last model year of the 1-year peel, which is the year
  # calculate_mohns_rho() compares for that peel
  retro_sb <- retro_fit[["estimates"]] |>
    dplyr::filter(label == "spawning_biomass") |>
    dplyr::select(label, year, estimated, retrospective_peel) |>
    tidyr::pivot_wider(names_from = retrospective_peel, values_from = estimated) |>
    dplyr::filter(year == 29) |>
    dplyr::select(-c(1, 2)) |>
    as.numeric()

  #' @description Test that the spawning biomass in year 29 from the base model
  #' and the 1-year peel match saved values.
  expect_equal(
    object = retro_sb,
    expected = c(1723.985, 1608.494),
    tolerance = 1e-3
  )
})

test_that("run_modified_data_fims() removes catch and keeps length_bin rows", {
  # The fleet1 length_bin rows are the only length data. They set the population
  # length bins that mean weight at age is averaged over, so the jnll changes if
  # they are dropped. Von Bertalanffy growth gives length at age, so the
  # age_to_length_conversion rows are not needed. The 3 bins cover a narrow
  # range to keep the fits fast.
  bins_data <- dplyr::bind_rows(
    dplyr::filter(
      data_big,
      !type %in% c("age_to_length_conversion", "length_comp")
    ),
    tibble::tibble(
      type = "length_bin",
      fleet = "fleet1",
      age = NA_real_,
      length = c(500, 550, 600),
      timing = NA_real_,
      observed = NA_real_,
      unit = NA_character_,
      uncertainty = NA_character_
    )
  )
  bins_frame <- FIMSFrame(bins_data)
  growth_parameters <- setup_default_parameters(bins_frame) |>
    dplyr::filter(module_name != "Growth") |>
    dplyr::bind_rows(setup_default_Growth(
      data = bins_frame,
      module_type = "VonBertalanffySchnute"
    ))
  # Peeling 1 year removes every row after year 29, including catch, except the
  # weight at age for year 30. It keeps the length_bin rows, which have no
  # timing. The parameters are set up from the peeled data, as
  # for a model with data that end in year 29.
  peeled_data <- dplyr::filter(
    bins_data,
    !(timing %in% 30 & type != "weight_at_age"),
    !(timing %in% 31)
  )
  peeled_frame <- FIMSFrame(peeled_data)
  peeled_parameters <- setup_default_parameters(peeled_frame) |>
    dplyr::filter(module_name != "Growth") |>
    dplyr::bind_rows(setup_default_Growth(
      data = peeled_frame,
      module_type = "VonBertalanffySchnute"
    ))

  retrospective_fit <- run_modified_data_fims(
    years_to_remove = 1,
    data = bins_data,
    parameters = growth_parameters
  )
  clear()
  peeled_fit <- peeled_parameters |>
    initialize_fims(data = peeled_frame) |>
    fit_fims(optimize = TRUE)
  clear()

  #' @description Test that run_modified_data_fims() removes the catch and the
  #' parameters after the last year and keeps the length_bin rows, so a 1-year
  #' peel gives the same jnll as a model set up from the data through year 29.
  expect_equal(
    object = get_report(retrospective_fit)[["jnll"]],
    expected = get_report(peeled_fit)[["jnll"]]
  )
})

## Edge handling ----
test_that("run_fims_retrospective() handles edge cases correctly", {
  #' @description Test that run_fims_retrospective works with years_to_remove = 0.
  retro_fit_zero <- run_fims_retrospective(
    years_to_remove = 0,
    data = data_big,
    parameters = parameters,
    n_cores = 1
  )
  expect_equal(
    object = length(retro_fit_zero[["years_to_remove"]]),
    expected = 1
  )
  expect_equal(
    object = retro_fit_zero[["years_to_remove"]],
    expected = 0
  )
})

test_that("run_modified_data_fims() removes a data type with no data left", {
  # The survey1 age compositions start in year 29, so a 2-year peel has none
  # left. FIMSFrame() fills years 1-28 with -999 rows, which cannot be fit.
  recent_data <- dplyr::filter(
    data_big,
    !(fleet == "survey1" & type == "age_comp" & timing < 29)
  )
  recent_parameters <- setup_default_parameters(FIMSFrame(recent_data))
  peeled_frame <- recent_data |>
    dplyr::filter(
      !(fleet == "survey1" & type == "age_comp"),
      is.na(timing) | timing <= 28 | (type == "weight_at_age" & timing == 29)
    ) |>
    FIMSFrame()
  peeled_fit <- setup_default_parameters(peeled_frame) |>
    initialize_fims(data = peeled_frame) |>
    fit_fims(optimize = TRUE)
  clear()
  raw_fit <- run_modified_data_fims(
    years_to_remove = 2,
    data = recent_data,
    parameters = recent_parameters
  )
  clear()
  frame_fit <- run_modified_data_fims(
    years_to_remove = 2,
    data = FIMSFrame(recent_data),
    parameters = recent_parameters
  )
  clear()

  #' @description Test that run_modified_data_fims() removes the survey1 age
  #' compositions when a peel has none left, for data that are and are not a
  #' FIMSFrame, so both give the same jnll as a model set up from the data
  #' through year 28.
  expect_equal(
    object = c(
      get_report(raw_fit)[["jnll"]],
      get_report(frame_fit)[["jnll"]]
    ),
    expected = rep(get_report(peeled_fit)[["jnll"]], 2)
  )
})

## Error handling ----
test_that("run_fims_retrospective() returns correct error messages", {
  #' @description Test that run_fims_retrospective errors with invalid n_cores (non-integer).
  expect_error(
    object = run_fims_retrospective(
      years_to_remove = 0:1,
      data = data_big,
      parameters = parameters,
      n_cores = 2.5
    ),
    regexp = "n_cores must be a positive integer"
  )

  #' @description Test that run_fims_retrospective errors with invalid n_cores (zero).
  expect_error(
    object = run_fims_retrospective(
      years_to_remove = 0:1,
      data = data_big,
      parameters = parameters,
      n_cores = 0
    ),
    regexp = "n_cores must be a positive integer"
  )

  #' @description Test that run_fims_retrospective errors with invalid n_cores (negative).
  expect_error(
    object = run_fims_retrospective(
      years_to_remove = 0:1,
      data = data_big,
      parameters = parameters,
      n_cores = -1
    ),
    regexp = "n_cores must be a positive integer"
  )

  #' @description Test that run_fims_retrospective errors with empty years_to_remove.
  expect_error(
    object = run_fims_retrospective(
      years_to_remove = numeric(0),
      data = data_big,
      parameters = parameters,
      n_cores = 1
    ),
    regexp = "must have at least one value"
  )

  #' @description Test that run_fims_retrospective errors with negative years_to_remove.
  expect_error(
    object = run_fims_retrospective(
      years_to_remove = -1,
      data = data_big,
      parameters = parameters,
      n_cores = 1
    ),
    regexp = "must contain non-negative values"
  )
})

test_that("calculate_mohns_rho() returns correct error messages", {
  #' @description Test that calculate_mohns_rho() errors with invalid retro_fit (not a list).
  expect_error(
    object = calculate_mohns_rho(
      retro_fit = "not_a_list",
      quantity = "spawning_biomass"
    ),
    regexp = "must be a list"
  )

  #' @description Test that calculate_mohns_rho() errors with missing elements in retro_fit.
  expect_error(
    object = calculate_mohns_rho(
      retro_fit = list(years_to_remove = 0:2),
      quantity = "spawning_biomass"
    ),
    regexp = "must contain 'years_to_remove' and 'estimates' elements"
  )

  #' @description Test that calculate_mohns_rho() errors with invalid quantity (not character).
  expect_error(
    object = calculate_mohns_rho(
      retro_fit = retro_fit,
      quantity = 123
    ),
    regexp = "must be a single character string"
  )

  #' @description Test that calculate_mohns_rho() errors with multiple quantities.
  expect_error(
    object = calculate_mohns_rho(
      retro_fit = retro_fit,
      quantity = c("spawning_biomass", "expected_recruitment")
    ),
    regexp = "must be a single character string"
  )

  #' @description Test that calculate_mohns_rho() errors when first model is not reference (retrospective_peel != 0).
  retro_fit_invalid <- retro_fit
  retro_fit_invalid$years_to_remove <- c(1, 2)

  expect_error(
    object = calculate_mohns_rho(
      retro_fit = retro_fit_invalid,
      quantity = "spawning_biomass"
    ),
    regexp = "must contain the reference run"
  )

  #' @description Test that calculate_mohns_rho() errors with non-existent quantity.
  expect_error(
    object = calculate_mohns_rho(
      retro_fit = retro_fit,
      quantity = "non_existent_quantity"
    ),
    regexp = "not found in estimates"
  )
})

## Warning handling ----
test_that("calculate_mohns_rho() handles warnings appropriately", {
  #' @description Test that calculate_mohns_rho() handles missing values gracefully.
  # Create a modified retro_fit with a missing value
  retro_fit_na <- retro_fit
  retro_fit_na[["estimates"]][["estimated"]][1] <- NA

  # Depending on where the NA is, this might produce a warning or still work
  # The function should handle this gracefully
  result <- tryCatch(
    {
      calculate_mohns_rho(retro_fit_na, quantity = "spawning_biomass")
    },
    warning = function(w) {
      # Check that warning message is appropriate
      expect_true(grepl("NA value|Missing value", w$message, ignore.case = TRUE))
      return(NULL)
    },
    error = function(e) {
      # If it errors, make sure it's an appropriate error
      expect_true(grepl("No valid|NA value|Missing value", e$message, ignore.case = TRUE))
      return(NULL)
    }
  )

  # If no warning/error is raised, verify a valid numeric return.
  if (!is.null(result)) {
    expect_true(is.numeric(result))
    expect_equal(length(result), 1)
  }
})
